"""Skill: tell the user which Wi-Fi network they're on."""

import re

from ai.response_generator import ResponseGenerator
from automation.system_control import get_wifi
from multitasking.async_executor import run_in_thread
from skills._base import Skill, SkillMatch, SkillResult

_PATTERN = re.compile(
    r"(what|which)\s+(wifi|wi-fi|network|internet)"
    r"|wifi\s+status|wi-fi\s+status|internet\s+connection"
)


class WifiSkill(Skill):
    name = "wifi"
    description = "Report current Wi-Fi network name"
    priority = 15

    def __init__(self):
        self._responses = ResponseGenerator()

    def match(self, text: str) -> SkillMatch | None:
        if _PATTERN.search(text.lower()):
            return SkillMatch(confidence=0.95)
        return None

    async def run(self, text: str, entities: dict) -> SkillResult:
        network = await run_in_thread(get_wifi)
        return SkillResult(text=self._responses.wifi_response(network))
